  'report.contents': '報告包含應用程式和版本號、作業系統和架構、時間、組件、階段、固定錯誤代碼、發生次數，以及最多 16 個固定轉換。帶有已清理診斷資訊的故障還會包含關聯 ID、固定原因和異常類、應用程式相對堆堆疊框架、受限上下文 ID、HTTP 狀態和經驗證的供應商請求 ID。報告不包含聊天、代理程式指令、供應商文字、金鑰、URL、主目錄路徑、進程輸出、剪貼簿、瀏覽器內容、螢幕截圖、原始記錄檔，也不包含請求或回應本文。可選的手動說明單獨處理，並會在提交前顯示。',
