  'report.consent': '此選擇在當前應用程式會話期間適用於您作業系統使用者配置檔案中的此安裝。它僅涵蓋啟用後的新故障。應用程式重啟後，自動報告預設為關閉；請在新會話中再次啟用。關閉後會停止後續自動重試，並移除未發送的自動報告。已被接收的報告無法通過此開關撤回。',
